(()=>{
const D=window.CITIES_DATA,$=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);
let city=D.cities.find(c=>c.id===params.get('city'))||D.cities[1];
let layer=city.layers.find(l=>l.id===params.get('layer'))||city.layers[city.id==='lachish'?1:0];
let find=Number(params.get('find'))||0,comparison=params.get('compare')==='1',expanded=params.get('record')==='1';
const short={jericho:['Destruction','Urban growth','Neolithic'],lachish:['Level II','Level III','Levels V–IV'],jerusalem:['Workshop reuse','Residences','Craft production'],corinth:['Later reuse','Roman colony','Greek & interim']};
const kind={jericho:['burn','wall','tower'],lachish:['wall','siege','wall'],jerusalem:['reuse','house','kiln'],corinth:['church','platform','column']};
function save(){const q=new URLSearchParams();q.set('city',city.id);q.set('layer',layer.id);q.set('find',String(find));if(comparison)q.set('compare','1');if(expanded)q.set('record','1');if($('restore').checked)q.set('restore','1');history.replaceState(null,'','?'+q);}
function links(ids){return [...new Set(ids)].map(id=>D.sources[id]).filter(Boolean).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)} ↗<span class="sr-only"> (opens in a new tab)</span></a>`).join('');}
function symbol(k,y){const base=`transform="translate(0 ${y})"`;
 if(k==='tower')return `<g ${base}><path class="arch" d="M266 71V33q34-16 65 0v38l-32 9Z"/><path d="M299 80V43m-25 9 46 -9" fill="none" stroke="var(--ochre)" stroke-width="3"/></g>`;
 if(k==='column')return `<g ${base}><path class="arch" d="M230 76V27h18v54m22 6V36h18v55m-65-64 73 18v-9l-73-18Z"/><path d="m305 91 47 -8" stroke="var(--char)" stroke-width="7"/></g>`;
 if(k==='platform'||k==='church')return `<g ${base}><path class="arch" d="m225 83 94 -20 65 21 -94 22Zm12-4V65l82 -19 51 18v17"/>${k==='church'?'<path class="arch" d="M270 75V42l36 -26 48 13v48l-46 13Z"/>':''}</g>`;
 if(k==='kiln')return `<g ${base}><path class="arch" d="M248 82V55q30 -43 61 0v27l-30 9Z"/><path d="M273 84V66q7-12 14 0v18" fill="var(--char)"/></g>`;
 if(k==='reuse')return `<g ${base}><path class="arch" d="m216 70 78 -15 89 27 -80 18Z"/><path d="m240 64 75 -15 0 14 -75 15Z" fill="var(--ochre)" stroke="var(--char)" stroke-width="2"/></g>`;
 return `<g ${base}><path class="arch" d="m170 63 131 -26 152 46 -23 8 -129 -38 -110 23v16l-21 -6Z"/><path class="arch" d="M207 79V50l23 -5v40m126 12V63l22 7v34"/>${k==='siege'?'<path d="m101 117 106 -67v29l-51 53Z" fill="var(--ochre)" stroke="var(--char)" stroke-width="2"/>':k==='burn'?'<path d="m230 94 18 -9 18 10 21 -7 29 13 22 -10" stroke="var(--char)" stroke-width="7" fill="none"/>':k==='house'?'<path d="m271 85 23 -4v6l18 6v7l18 6" stroke="var(--char)" stroke-width="3" fill="none"/>':''}</g>`;
}
function art(){const selected=city.layers.indexOf(layer);$('art-layers').innerHTML=[2,1,0].map(i=>{const y=i*112,burn=(city.id==='jericho'&&i===0)||(city.id==='lachish'&&i<2)||(city.id==='jerusalem'&&i===1);return `<g class="earth-layer layer-${i} ${burn?'burn-layer':''} ${selected===i?'selected':''}" data-horizon="${i}" style="cursor:pointer"><path class="layer-front" d="M69 ${111+y}L328 ${179+y}V${217+y}L69 ${149+y}Z"/><path class="layer-side" d="M328 ${179+y}L566 ${124+y}V${162+y}L328 ${217+y}Z"/><path class="layer-top" d="M69 ${111+y}L298 ${61+y} 566 ${124+y} 328 ${179+y}Z"/><path d="M69 ${111+y}L328 ${179+y}V${217+y}L69 ${149+y}Z" fill="url(#${burn?'ash':'soil'})"/>${symbol(kind[city.id][i],y)}<circle cx="600" cy="${139+y}" r="14" fill="${selected===i?'var(--accent)':'var(--surface)'}" stroke="var(--line)"/><text x="600" y="${144+y}" text-anchor="middle" font-family="Arial" font-size="13" fill="${selected===i?'var(--paper)':'var(--ink)'}">${i+1}</text><path d="M566 ${142+y}H582" stroke="var(--line)"/></g>`;}).join('');
 document.querySelectorAll('[data-horizon]').forEach(g=>g.onclick=()=>selectLayer(Number(g.dataset.horizon)));
}
function chooseCity(id){city=D.cities.find(c=>c.id===id);layer=city.layers[city.id==='lachish'?1:0];find=0;render();save();document.querySelector(`[data-city="${id}"]`).focus({preventScroll:true});}
function selectLayer(i){layer=city.layers[i];find=0;render();save();document.querySelector(`[data-layer="${i}"]`).focus({preventScroll:true});}
function setFind(i){find=i;renderFind();save();document.querySelector(`[data-find="${i}"]`)?.focus({preventScroll:true});}
function renderFind(){const f=layer.finds[find]||layer.finds[0];$('find-buttons').innerHTML=layer.finds.length>1?layer.finds.map((v,i)=>`<button type="button" data-find="${i}" aria-pressed="${i===find}">${esc(v.label)}</button>`).join(''):'';
 $('find-detail').innerHTML=`<h4>${esc(f.label)}</h4><p>${esc(f.evidence)}</p><p style="margin-top:10px">${esc(f.inference)}</p><div class="links">${links(f.sources)}</div>`;
 const grain=/grain|charcoal/i.test(f.label);$('find-object').innerHTML=`<svg viewBox="0 0 210 150" aria-hidden="true">${grain?'<ellipse cx="105" cy="120" rx="70" ry="10" fill="var(--shadow)"/><g fill="var(--ochre)" stroke="var(--accent)" stroke-width="1.4"><ellipse cx="70" cy="82" rx="11" ry="23" transform="rotate(-25 70 82)"/><ellipse cx="110" cy="71" rx="12" ry="25" transform="rotate(30 110 71)"/><ellipse cx="135" cy="100" rx="11" ry="22" transform="rotate(70 135 100)"/></g><path d="m63 63 16 39m43 -52 -23 43m16 14 36 -15" stroke="var(--accent)" fill="none"/>':'<ellipse cx="105" cy="130" rx="72" ry="9" fill="var(--shadow)"/><path d="m48 39 89 -13 35 32 -14 61 -94 7 -26 -36Z" fill="var(--clay)" stroke="var(--accent)" stroke-width="2"/><path d="m48 39 12 14 72 -11 40 16M60 53l4 73" fill="none" stroke="var(--chalk)" stroke-width="3"/>'}</svg><small>${grain?'Illustrative material forms':'Illustrative fragment · no inscription reproduced'}</small>`;
 document.querySelectorAll('[data-find]').forEach(b=>b.onclick=()=>setFind(Number(b.dataset.find)));
}
function compareRender(){const other=city.layers.find(l=>l.id!==layer.id);$('comparison').hidden=!comparison;$('compare').setAttribute('aria-expanded',String(comparison));$('compare').innerHTML=`${comparison?'Close comparison':'Compare with '+esc(short[city.id][city.layers.indexOf(other)])}<span>${comparison?'×':'↓'}</span>`;$('comparison-title').textContent=city.id==='lachish'&&[layer.id,other.id].includes('ii')&&[layer.id,other.id].includes('iii')?'Rebuilding separates the two crises.':'Two contexts, held apart.';
 $('comparison-content').innerHTML=[layer,other].map(l=>`<article><p class="date">${esc(l.date)}</p><h4>${esc(l.name)}</h4><span class="label">Excavated feature</span><p>${esc(l.feature)}</p><span class="label">Historical association</span><p>${esc(l.association)}</p><div class="links">${links(l.sources)}</div></article>`).join('');}
function recordRender(){const inv=D.investigations[city.id];$('full-record').hidden=!expanded;$('open-record').setAttribute('aria-expanded',String(expanded));$('open-record').innerHTML=`${expanded?'Close the excavation record':'Open the excavation record & argument'} <span>${expanded?'×':'↓'}</span>`;
 $('full-record').innerHTML=`<h3>${esc(inv.question)}</h3><h4>Evidence</h4><p>${esc(inv.observation)}</p><h4>Argument</h4><p>${esc(inv.reasoning)}</p><h4>Limits</h4><p>${esc(inv.limit)}</p><p>${esc(inv.implication)}</p><h4>Excavation context</h4><p>${esc(city.excavation)}</p><h4>Reconstruction</h4><p>${esc(layer.reconstruction)}</p><p>${esc(city.intro)}</p><div class="links"><a href="${esc(D.research.find(s=>s.id===inv.source).url)}" target="_blank" rel="noopener noreferrer">Read the research ↗</a></div><p class="caption">${esc(D.research.find(s=>s.id===inv.source).access)}</p><button id="bottom-close" class="full-record-control" type="button">Close record & return to its opening <span>×</span></button>`;
 $('bottom-close').onclick=()=>toggleRecord(false,true);
}
function render(){const i=city.layers.indexOf(layer);$('cities').innerHTML=D.cities.map((c,j)=>`<button type="button" data-city="${c.id}" aria-pressed="${c.id===city.id}"><small>0${j+1}</small>${esc(c.name)}</button>`).join('');document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>chooseCity(b.dataset.city));
 $('city-name').textContent=city.name;$('city-region').textContent=city.region;$('record-date').textContent=layer.date;$('record-title').textContent=layer.name;$('observation').textContent=layer.feature;$('dating').textContent=layer.dating;$('limit').textContent=layer.association;$('record-links').innerHTML=links(layer.sources);
 $('layers').innerHTML=city.layers.map((l,j)=>`<button type="button" data-layer="${j}" aria-pressed="${j===i}" aria-controls="record"><span>${j+1}</span><span><strong>${esc(short[city.id][j])}</strong><small>${esc(l.date)}</small></span></button>`).join('');document.querySelectorAll('[data-layer]').forEach(b=>b.onclick=()=>selectLayer(Number(b.dataset.layer)));
 $('section-limit').textContent=city.id==='jerusalem'?'Separate excavation locations, arranged for comparison. These buildings were not found stacked above one another. Invented geometry; no depth or time scale.':city.id==='jericho'?'Composite teaching section. Urban growth summarizes several periods, not one sealed layer below the destruction. Geometry and spacing are illustrative.':'Composite teaching section. Depth, thickness and architecture are illustrative; the spaces between blocks do not measure time.';
 $('daily').textContent=layer.daily;$('passage').innerHTML=layer.passage?`<span class="label">Read the passage in context</span><a href="http://127.0.0.1:8931/read/kjv/${layer.passage.book}/${layer.passage.chapter}">${esc(layer.passage.label)} ↗</a><p>${esc(layer.passage.note)}</p>`:'<span class="label">No direct biblical association</span><p>This horizon matters without assigning it a biblical event.</p>';
 art();renderFind();compareRender();recordRender();$('status').textContent=`${city.name}: ${layer.name} selected. Evidence is in the record alongside the section.`;
}
function closeComparison(){comparison=false;compareRender();save();$('compare').focus({preventScroll:true});const r=$('compare').getBoundingClientRect();if(r.top<64||r.bottom>innerHeight)$('compare').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}
function toggleRecord(open,returnFocus=false){expanded=open;recordRender();save();if(returnFocus){$('open-record').focus({preventScroll:true});$('open-record').scrollIntoView({block:'center',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}}
 $('compare').onclick=()=>{if(comparison)closeComparison();else{comparison=true;compareRender();save();}};$('close-comparison').onclick=closeComparison;$('open-record').onclick=()=>toggleRecord(!expanded);$('restore').checked=params.get('restore')==='1';$('restoration').hidden=!$('restore').checked;$('restore').onchange=e=>{$('restoration').hidden=!e.target.checked;save();};
 $('theme').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('theme').textContent=dark?'Light':'Dark';$('theme').setAttribute('aria-label',`Switch to ${dark?'light':'dark'} theme`);};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(expanded)toggleRecord(false,true);else if(comparison)closeComparison();}});
 render();
})();
